entries[22549] = { ["name"] = "Sathiels Auftrag", ["text"] = "Questgegenstand\nEinzigartig\n\"Das Geschriebene passt kaum auf die Seite. Wer soll bloß all das tragen?\"" }
entries[22550] = { ["name"] = "Sathiels Waren", ["text"] = "Questgegenstand\nEinzigartig\n\"Ihr seid Euch nicht sicher, aber es hörte sich an, als ob im Inneren etwas zerbrochen wäre.\"" }
entries[22551] = { ["name"] = "Formel: Waffe - Erhebliche Intelligenz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Erhebliche Intelligenz' bei Waffen durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass die Intelligenz um 12 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (40)\nVerkaufspreis:" }
entries[22552] = { ["name"] = "Formel: Waffe - Erhebliches Schlagen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Erhebliches Schlagen' durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass damit zusätzlich 6 Schaden verursacht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (40)\nBenötigt Das Konsortium\n- Wohlwollend\nVerkaufspreis:" }
