entries[22555] = { ["name"] = "Formel: Waffe - Erhebliche Zaubermacht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Erhebliche Zaubermacht' bei Waffen durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass die Zaubermacht um 16 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (50)\nVerkaufspreis:" }
