entries[22557] = { ["name"] = "Formel: Waffe - Meister des Kampfes", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Meister des Kampfes' durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass sie Gruppenmitglieder in der Nähe gelegentlich um 3797 Gesundheit heilt, wenn ein Nahkampfangriff durchgeführt wird. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (60)\nVerkaufspreis:" }
entries[22558] = { ["name"] = "Formel: Waffe - Zauberflut", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Zauberflut' durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass beim Zauberwirken manchmal bei Gruppenmitgliedern in der Nähe 3750 Mana wiederhergestellt wird. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (60)\nVerkaufspreis:" }
entries[22559] = { ["name"] = "Formel: Waffe - Mungo", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Mungo' durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass gelegentlich Eure Beweglichkeit um 24 und Euer Tempo um 6 erhöht wird. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (75)\nVerkaufspreis:" }
entries[22560] = { ["name"] = "Formel: Waffe - Sonnenfeuer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Sonnenfeuer' durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass die Feuer- und die Arkanzaubermacht um 10 erhöht werden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (75)\nVerkaufspreis:" }
entries[22561] = { ["name"] = "Formel: Waffe - Seelenfrost", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Seelenfrost' durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass die Frost- und die Schattenzaubermacht um 10 erhöht werden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (75)\nVerkaufspreis:" }
entries[22562] = { ["name"] = "Formel: Überragendes Manaöl", ["text"] = "Benutzen: Lehrt Euch die Herstellung von überragendem Manaöl.\nErstellt Überragendes Manaöl.\nBenötigt Verzauberkunst der Scherbenwelt (10)\nVerkaufspreis:\nÜberragendes Manaöl\nBenutzen: Trägt überragendes Manaöl auf Eure Waffe auf, das Eure Vielseitigkeit um 11 erhöht. Hält 1 Stunde lang an. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\n5 Aufladungen\nVerkaufspreis:\nBenötigt Arkaner Staub (3), Netherblüte , Kristallphiole" }
entries[22563] = { ["name"] = "Formel: Überragendes Zauberöl", ["text"] = "Benutzen: Lehrt Euch die Herstellung von überragendem Zauberöl.\nErstellt Überragendes Zauberöl.\nBenötigt Verzauberkunst der Scherbenwelt (40)\nVerkaufspreis:\nÜberragendes Zauberöl\nBenutzen: Trägt überragendes Zauberöl auf Eure Waffe auf, das Eure Intelligenz um 17 erhöht. Hält 1 Stunde lang an. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\n5 Aufladungen\nVerkaufspreis:\nBenötigt Arkaner Staub (3), Alptraumranke , Kristallphiole" }
entries[22564] = { ["name"] = "Formel: Arkaner Staub", ["text"] = "Benutzen: Lehrt Euch, einen arkanen Kristall in arkanen Staub umzuwandeln.\nWandelt einen Arkankristall in arkanen Staub um.\nBenötigt Verzauberkunst der Scherbenwelt (25)\nVerkaufspreis:\nArkaner Staub\nHandwerksmaterial\nBenötigt Arkankristall" }
entries[22565] = { ["name"] = "Formel: Großer Prismasplitter", ["text"] = "Benutzen: Lehrt Euch, kleine Prismasplitter in einen großen Prismasplitter umzuwandeln.\nWandelt drei kleine Prismasplitter in einen großen Prismasplitter um.\nBenötigt Verzauberkunst der Scherbenwelt (35)\nVerkaufspreis:\nGroßer Prismasplitter\nHandwerksmaterial\nBenötigt Kleiner Prismasplitter (3)" }
