entries[22589] = { ["name"] = "Atiesh, Hohestab des Wächters", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+16 Intelligenz\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 145 / 145\nKlassen: Magier\nAnlegen: Erhöht den kritischen Zaubertrefferwert aller Gruppenmitglieder innerhalb von 30 Metern um 6 .\nBenutzen: Lässt ein Portal entstehen, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert. (1 Min Abklingzeit)\nVerkaufspreis:" }
