entries[22900] = { ["name"] = "Rezept: Elixier der Tarnung", ["text"] = "Benutzen: Lehrt euch, wie man ein Elixier der Tarnung herstellt.\nBenötigt Alchemie der Scherbenwelt\n(5)\nVerkaufspreis:\nElixier der Tarnung\nBenutzen: Anwender kann 1 Stunde lang nicht aufgespürt werden. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Zottelkappe , Teufelsgras , Kristallphiole" }
entries[22901] = { ["name"] = "Rezept: Schleichtrank", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Schleichtranks.\nBenötigt Alchemie der Scherbenwelt\n(15)\nVerkaufspreis:\nSchleichtrank\nBenutzen: Erhöht Eure Verstohlenheit 1 Min. lang um einen großen Betrag. Funktioniert nicht über Stufe 49. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zottelkappe (2), Teufelsgras , Kristallphiole" }
