entries[22903] = { ["name"] = "Rezept: Trank der Wahnsinnsstärke", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Tranks der Wahnsinnsstärke.\nBenötigt Alchemie der Scherbenwelt\n(20)\nVerkaufspreis:\nTrank der Wahnsinnsstärke\nBenutzen: Erhöht Eure Stärke um 38 und verringert Euer Ausweichen um 24 . Hält 15 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Terozapfen (3), Kristallphiole" }
