entries[22911] = { ["name"] = "Rezept: Erheblicher Trank des traumlosen Schlafs", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines erheblichen Tranks des traumlosen Schlafs.\nBenötigt Alchemie der Scherbenwelt\n(50)\nVerkaufspreis:\nErheblicher Trank des traumlosen Schlafs\nBenutzen: Versetzt den Anwender 12 Sek. lang in einen traumlosen Schlaf. Während dieser Zeit regeneriert der Anwender ( 51 * 4) Gesundheit und ( 51 * 4) Mana. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Traumwinde , Alptraumranke , Kristallphiole" }
